CREATE OR REPLACE FUNCTION lab.last_chars (p_text varchar, p_n numeric)
RETURNS varchar
LANGUAGE plpgsql
SET search_path = lab, public
AS $$
DECLARE
  v_n integer := trunc(p_n);
BEGIN
  IF v_n > 0 THEN
    IF v_n > length(p_text) THEN
      RETURN NULL;
    END IF;
    RETURN NULLIF(right(p_text, v_n), '');
  ELSIF v_n = 0 THEN
    RETURN NULLIF(p_text, '');
  END IF;
  RETURN NULLIF(substr(p_text, -v_n), '');
END;
$$;
